// remote directory where CA trust anchors are stored inside the Podman machine
const REMOTE_ANCHORS_PATH = '/etc/pki/ca-trust/source/anchors';

// prefix used for certificate files managed by Podman Desktop
const CERT_FILE_PREFIX = 'podman-desktop-';

// number of hex characters kept from the SHA-256 hash to identify a certificate
const FINGERPRINT_LENGTH = 16;

// the certificate stores that make up the host trust set
const CERTIFICATE_STORES = ['system', 'bundled', 'extra'] as const;

/**
 * Manages synchronization of host system TLS certificates into running Podman virtual machines.
 */
export class PodmanCertificateSync {
  constructor(
    private readonly machineStatuses: Map<string, ProviderConnectionStatus>,
    private readonly machineInfos: Map<string, MachineInfo>,
  ) {}

  /**
   * Collect the trusted certificates of the host, merging the 'system', 'bundled' and 'extra'
   * certificate stores and removing any duplicates.
   */
  getSystemCertificates(): string[] {
    const collected: string[] = [];
    for (const store of CERTIFICATE_STORES) {
      collected.push(...tls.getCACertificates(store));
    }
    // remove duplicates while preserving insertion order
    return Array.from(new Set(collected));
  }

  /**
   * Return the names of the machines that are started and have a known vmType.
   */
  getRunningMachineNames(): string[] {
    const names: string[] = [];
    for (const [name, status] of this.machineStatuses) {
      if (status !== 'started') {
        continue;
      }
      const info = this.machineInfos.get(name);
      if (!info || !info.vmType || info.vmType.trim().length === 0) {
        continue;
      }
      names.push(name);
    }
    return names;
  }

  /**
   * Synchronize the host certificates into every running Podman machine. A failure while
   * synchronizing one machine does not prevent the remaining machines from being processed.
   */
  async synchronizeAll(): Promise<void> {
    const runningMachines = this.getRunningMachineNames();
    if (runningMachines.length === 0) {
      await extensionApi.window.showWarningMessage('No running Podman machines found.');
      return;
    }

    const certificates = this.getSystemCertificates();
    for (const machineName of runningMachines) {
      try {
